def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find connected components of nonzero, non-5 cells.
    comp_id = [[-1] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or grid[r][c] == 5 or comp_id[r][c] >= 0:
                continue
            k = len(comps)
            stack = [(r, c)]
            comp_id[r][c] = k
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        grid[ny][nx] not in (0, 5) and comp_id[ny][nx] < 0):
                        comp_id[ny][nx] = k
                        stack.append((ny, nx))
            comps.append(cells)

    # Find maximal straight runs of 5s.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5 or (c > 0 and grid[r][c - 1] == 5):
                c += 1
                continue
            end = c
            while end + 1 < w and grid[r][end + 1] == 5:
                end += 1
            if end > c:
                runs.append(("H", r, c, end))
            c = end + 1

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5 or (r > 0 and grid[r - 1][c] == 5):
                r += 1
                continue
            end = r
            while end + 1 < h and grid[end + 1][c] == 5:
                end += 1
            if end > r:
                runs.append(("V", c, r, end))
            r = end + 1

    for orient, fixed, start, end in runs:
        touching = set()
        for t in range(start, end + 1):
            if orient == "H":
                for nr, nc in ((fixed - 1, t), (fixed + 1, t)):
                    if 0 <= nr < h and grid[nr][nc] not in (0, 5):
                        touching.add(comp_id[nr][nc])
            else:
                for nr, nc in ((t, fixed - 1), (t, fixed + 1)):
                    if 0 <= nc < w and grid[nr][nc] not in (0, 5):
                        touching.add(comp_id[nr][nc])

        touching.discard(-1)
        for k in touching:
            cells = comps[k]
            r0 = min(r for r, c in cells)
            r1 = max(r for r, c in cells)
            c0 = min(c for r, c in cells)
            c1 = max(c for r, c in cells)

            if orient == "H":
                # Repeat the adjacent tile horizontally along the 5-line.
                for c in range(start, end + 1):
                    src_c = c0 + (c - c0) % (c1 - c0 + 1)
                    for r in range(r0, r1 + 1):
                        out[r][c] = grid[r][src_c]
            else:
                # Repeat the adjacent tile vertically along the 5-line.
                for r in range(start, end + 1):
                    src_r = r0 + (r - r0) % (r1 - r0 + 1)
                    for c in range(c0, c1 + 1):
                        out[r][c] = grid[src_r][c]

    return out
